import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
const dir=path.dirname(fileURLToPath(import.meta.url));
const root=process.cwd();
const manifest=JSON.parse(fs.readFileSync(path.join(dir,'release-manifest.json'),'utf8'));
const allowed=new Set(manifest.files.map(f=>f.key));
const server=http.createServer(async(req,res)=>{
 try{
  const key=decodeURIComponent(new URL(req.url,'http://127.0.0.1').pathname).slice(1);
  if(req.method!=='GET'||key.includes('..')||!key.startsWith('app/')){res.writeHead(404).end();return;}
  res.setHeader('Access-Control-Allow-Origin','*');
  if(allowed.has(key)){
   const local=path.join(root,'.local/r2',key);
   res.writeHead(200,{'Content-Type':'application/json','X-Theme-Preview-Source':'staged'});
   res.end(fs.readFileSync(local));return;
  }
  const upstream=await fetch('https://storage.stats47.jp/'+key,{signal:AbortSignal.timeout(20000)});
  res.writeHead(upstream.status,{'Content-Type':upstream.headers.get('content-type')??'application/json','X-Theme-Preview-Source':'public'});
  res.end(Buffer.from(await upstream.arrayBuffer()));
 }catch(e){res.writeHead(502).end(JSON.stringify({error:'preview data unavailable'}));}
});
server.listen(4778,'127.0.0.1',()=>console.log('Theme preview gateway on 127.0.0.1:4778; staged files '+allowed.size));
